// Select all paragraphs in div.txt
const nodes = Array.from(document.querySelectorAll("div.txt p"));

// Filter out translator/editor lines, empties, and the specified novel promotion line
const filteredList = nodes
  .map(p => p.innerText.trim())
  .filter(t => 
    t && 
    !t.startsWith("Translator:") && 
    !t.startsWith("Editor:") && 
    t !== "Visit and read more novel to help us update chapter quickly. Thank you so much!"
  );

// FORMAT THE DATA: Join the array into a single string with double newlines
// Use '\n' for single spacing or '\n\n' for paragraph spacing
const formattedText = filteredList.join('\n\n');

// Save the cleaned, formatted string to the variable
automaSetVariable('filteredText', formattedText);

